    add(base, lathe([[0.0142, 44e-4], [0.0142, 72e-4], [0.0128, 84e-4], [0.0112, 84e-4], [0.0112, Y_PIVOT - 0.0205], [0.0124, Y_PIVOT - 0.0195], [0.0124, Y_PIVOT - 0.017], [0, Y_PIVOT - 0.017]], 48), M.aluBright);
